alter table public.usp_items add column if not exists icon_alt text;
update public.settings set value='{"kicker": "O nas", "heading": "Warsztat samochodowy – Soft Car Service w&nbsp;Czechowicach-Dziedzicach", "body_html": "<p>Soft Car Service to&nbsp;zaufany <strong>serwis samochodowy</strong>, który służy mieszkańcom Czechowic-Dziedzic i&nbsp;okolic. Specjalizujemy&nbsp;się w&nbsp;<a href=\"/oferta/mechanika-oraz-diagnostyka-samochodowa\">naprawie samochodów osobowych i&nbsp;dostawczych</a>, oferując szeroki zakres usług, od&nbsp;przeglądów technicznych po&nbsp;skomplikowane naprawy mechaniczne. Nasz&nbsp;zespół to&nbsp;doświadczeni mechanicy, którzy z&nbsp;pasją podchodzą do&nbsp;swojej pracy, gwarantując najwyższą jakość usług. Dzięki nowoczesnemu sprzętowi i&nbsp;ciągłemu doskonaleniu umiejętności jesteśmy w&nbsp;stanie sprostać największym wyzwaniom.</p>", "cta": {"title": "Poznaj nas bliżej!", "body_html": "<p>Chcesz dowiedzieć&nbsp;się więcej o&nbsp;naszym autoserwisie i&nbsp;ofercie? Kliknij przycisk poniżej!</p>", "button_label": "Dowiedz&nbsp;się o&nbsp;nas więcej", "button_href": "/o-nas"}}'::jsonb, label='Strona główna — sekcja O nas' where key='home_about';
update public.settings set value='{"kicker": "To co nas wyróżnia"}'::jsonb where key='home_usp';
update public.settings set value='{"kicker": "Nasze osiągnięcia", "heading": "Wieloletnie doświadczenie na rynku", "body_html": "<p>Jesteśmy firmą z wieloletnim doświadczeniem na rynku. Przez lata zdobywaliśmy zaufanie klientów, którzy docenili nasze profesjonalne podejście do pracy. Nasze osiągnięcia to efekt ciężkiej pracy, pasji i zaangażowania. Dzięki temu możemy dzisiaj oferować usługi na najwyższym poziomie.</p>"}'::jsonb where key='home_counters';
update public.settings set value='{"heading": "Zapraszamy do&nbsp;kontaktu!", "body_html": "<p><strong>Jeżeli macie jakiekolwiek pytania lub&nbsp;potrzebujecie dodatkowych informacji, zapraszamy do&nbsp;skontaktowania&nbsp;się z&nbsp;nami. Jesteśmy gotowi udzielić wszelkich wyjaśnień i&nbsp;przygotować spersonalizowaną wycenę, dopasowaną do&nbsp;Waszych potrzeb.</strong></p>\n<a href=\"/o-nas\" class=\"btn border-radius-sm btn-shadow\">Skontaktuj&nbsp;się z&nbsp;nami</a>", "button": {"label": "Skontaktuj się z nami", "href": "/o-nas"}}'::jsonb where key='home_parallax';
update public.settings set value='{"kicker": "Oferta", "heading": "Zapraszamy do zapoznania się z naszą ofertą. Gwarantujemy profesjonalne usługi na&nbsp;najwyższym poziomie."}'::jsonb where key='home_offer';
update public.usp_items set icon_alt='Ikona człowieka na&nbsp;dłoni' where icon='/images/design/icon-usp-1.webp';
update public.usp_items set icon_alt='Ikona tarczy' where icon='/images/design/icon-usp-2.webp';
update public.usp_items set icon_alt='Ikona terminarza' where icon='/images/design/icon-usp-3.webp';
update public.usp_items set icon_alt='Ikona ręki i&nbsp;haczyka' where icon='/images/design/icon-usp-4.webp';
